(x, y, t) => {
  const cx = 240, cy = 120;
  const wells = [
    [160+Math.sin(t*0.5)*100, 80+Math.cos(t*0.4)*50, 40],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.65)*50, 35],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 50],
    [100+Math.cos(t*0.7+1)*80, 180+Math.sin(t*0.55+3)*60, 30],
    [380+Math.sin(t*0.35+4)*90, 60+Math.cos(t*0.8+2)*70, 38],
    [240+Math.cos(t*0.3+5)*120, 200+Math.sin(t*0.5)*80, 42],
    [60+Math.sin(t*0.6+3)*60, 40+Math.cos(t*0.7)*50, 28],
    [420+Math.cos(t*0.5+2)*50, 220+Math.sin(t*0.4+1)*40, 32]
  ];
  let gx = 0, gy = 0;
  for (const [wx, wy, mass] of wells) {
    const dx = wx - x, dy = wy - y;
    const dist = Math.max(10, Math.sqrt(dx*dx + dy*dy));
    const force = mass / (dist * 0.5);
    gx += dx/dist * force;
    gy += dy/dist * force;
  }
  const wx = Math.sin(x*0.018 + t*0.25) * 20 + Math.cos(y*0.012 - t*0.18) * 15 + gx*0.3;
  const wy = Math.cos(y*0.016 - t*0.2) * 20 + Math.sin(x*0.014 + t*0.3) * 15 + gy*0.3;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.1, 2.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.12, 2.0],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.08, 2.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.14, 1.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.09, 3.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.11, 2.3],
    [80+Math.sin(t*0.65+3)*70, 30+Math.cos(t*0.75)*50, 0.13, 1.9],
    [400+Math.cos(t*0.5+2)*60, 200+Math.sin(t*0.45+1)*50, 0.1, 2.6]
  ];
  let aS = 0, iS = 0, eng = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    eng += Math.sin(d*f*0.3 + t*sp*1.2) * Math.cos(d*f*0.5 - t*sp*0.8);
  }
  const act = aS/8, inh = iS/8, energy = eng/8;
  const bg = (Math.sin(sx*0.05+sy*0.03+t*0.9)+Math.sin(sx*0.035-sy*0.045+t*1.3))/2 + Math.sin((sx+sy)*0.15+t*3)*0.25 + Math.sin((sx-sy)*0.12-t*2.5)*0.25;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.06-ang*4-t*1.8)+Math.sin(dist*0.05+ang*5-t*1.4))*0.5;
  const potential = Math.sin(dist*0.03-t*0.5)*Math.cos(ang*2+t*0.3);
  const kinetic = Math.sin(dist*0.08+ang*3+t*2)*0.5;
  const cascade = potential*0.6+kinetic*0.4;
  const reaction = Math.tanh((act-inh*0.65+bg*0.25+spiral*0.4+energy*0.35+cascade*0.2)*3.0);
  const cell = Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18)+Math.sin((sx+sy)*0.12+t)*0.5)*2.5)*0.35;
  const rd2 = Math.tanh((Math.sin(sx*0.12-t*0.8)*Math.cos(sy*0.1+t*0.6)+Math.sin(dist*0.04-ang*2+t)*0.6)*2.0)*0.3;
  const blend = reaction*0.6+cell*0.2+rd2*0.2, v = blend*0.5+0.5;
  const pal = [[5,2,20],[10,0,40],[180,0,255],[0,255,200],[255,255,0],[255,50,100],[0,100,255],[255,0,150],[0,255,100],[5,2,20]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const edgeGlow = Math.abs(reaction)>0.6?1.0+Math.abs(reaction)*0.6:0.85+Math.abs(reaction)*0.3;
  const lum = edgeGlow*(1.0+Math.abs(energy)*0.2);
  const neonBoost = v>0.35&&v<0.75?1.3:1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*neonBoost)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*neonBoost)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*neonBoost)|0
  ];
}
